-- PDPL: put the reversed-group mobile layer back on top of the coordinate guard (2026-10-02).
--
-- Two full-function migrations landed 25 seconds apart: 20261002151443 (the shapes layer learns the
-- RTL-reversed mobile «00 44 33 0502») and 20261002151508 (the legacy rules stop cutting map
-- coordinates). The second was built from the older function body, so applying it silently
-- removed the first one's layer from public._redact_pii_sql: for a short time the floor stopped
-- redacting «للتواصل : 00 44 33 0502» on new writes (stored rows were never touched; the monitors and
-- scrapers/common/pii.py kept the layer throughout).
--
-- This is the union, as one full function: the shapes layer of 20261002151443 byte-for-byte
-- (scrapers/common/pii.py _PHONE_SHAPES_RE) and the two legacy layers of 20261002151508 behind
-- _NOT_IN_A_COORDINATE. mon_check_pii_leaks() and mon_scan_pii_capture_batch() already carry both
-- changes (checked live before this was written), so only the floor is replaced. The tests pin the
-- LATEST function-defining migration, which is this one.
create or replace function public._redact_pii_sql(t text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select nullif(btrim(regexp_replace(
    regexp_replace(
    regexp_replace(
    regexp_replace(
    regexp_replace(
    regexp_replace(
    regexp_replace(
